(() => {
  const b = bb(params.bbPeriod, params.bbMult);
  const r = rsi(c, params.rsiPeriod);
  const a = atr(params.atrPeriod);
  const trend = adx(params.adxPeriod).adx;

  if (na(b.lower[i]) || na(r[i]) || na(a[i])) return { side: 'flat', strength: 0, reason: 'warmup' };
  const chop = na(trend[i]) ? true : trend[i] < params.adxMax;

  if (c[i] <= b.lower[i] && r[i] < params.rsiOversold && chop) {
    return {
      side: 'long',
      strength: clamp((params.rsiOversold - r[i]) / 30, 0.1, 1),
      reason: 'close under lower band, RSI=' + round(r[i], 1) + ', ADX=' + round(trend[i], 1),
      stopLoss: c[i] - a[i] * params.atrStopMult,
      takeProfit: b.middle[i]
    };
  }
  if (c[i] >= b.upper[i] && r[i] > params.rsiOverbought && chop) {
    return {
      side: 'short',
      strength: clamp((r[i] - params.rsiOverbought) / 30, 0.1, 1),
      reason: 'close above upper band, RSI=' + round(r[i], 1) + ', ADX=' + round(trend[i], 1),
      stopLoss: c[i] + a[i] * params.atrStopMult,
      takeProfit: b.middle[i]
    };
  }
  return { side: 'flat', strength: 0, reason: 'inside-band' };
})()
